export function verifyCapturedGunRecord(record){assert.equal(record.parent,PARENT);const inputs=capturedCategoryInputs(record);assert.deepEqual(record.categories.map(c=>c.name),CAPTURED_GUNS_NAMES);assert.equal(record.controls.length,12);const controls=inputs.map((d,i)=>{assert.equal(record.categories[i].dataSha256,hash(rawText(d)));verifyCapturedGun(i,d);let error;try{verifyCapturedGun(i,capturedGunMutation(i,d));}catch(e){error=e;}assert.equal(error?.code,'ERR_ASSERTION');assert.equal(error.message,CAPTURED_GUNS_NAMES[i]);return{name:CAPTURED_GUNS_NAMES[i],code:error.code,message:error.message};});assert.deepEqual(record.controls,controls);return inputs;}

export const CAPTURED_GUNS_HARNESS = `async function capturedGunsModelUnit() {
  try {
    const { execFileSync } = await import('node:child_process');
    const text = execFileSync(process.execPath, [path.join(ROOT, 'tools/test-captured-guns.mjs')], { encoding: 'utf8', maxBuffer: 4 * 1024 * 1024 });
    const lines = text.trimEnd().split('\\n'), rows = lines.filter(l => l.startsWith('CAPTURED GUNS ACTUAL '));
    if (rows.length !== 1 || !lines.includes('CAPTURED GUNS OK (12/12)')) throw new Error('Incomplete captured-gun proof.');
    const actual = JSON.parse(rows[0].slice('CAPTURED GUNS ACTUAL '.length));
    const { verifyCapturedGunRecord } = await import('./test-captured-guns.mjs');
    verifyCapturedGunRecord(actual);
    result.capturedGuns = actual;
    check('captured-guns-model', true, '12 actual CPU categories and 12 own controls; original A/B/A2, current66 source guards');
  } catch (error) { check('captured-guns-model', false, error.message); }
}

`;

