export function sourceProof(){const sourcePaths=[...JSON.parse(fs.readFileSync(ROOT+'/tools/test-surrender-result-ui.mjs','utf8').match(/^const SOURCE_PATHS = (\[[^\n]+\]);/m)[1]),'tools/test-keyboard-ui.mjs','tools/test-surrender-activation.mjs','tools/test-surrender-activation-ui.mjs','tools/test-captured-guns.mjs'];assert.equal(sourcePaths.length,66);assert.equal(new Set(sourcePaths).size,66);const sources=[],parentBindings=[];let changed=0;for(const path of sourcePaths){const b=fs.readFileSync(ROOT+'/'+path);sources.push({path,bytes:b.length,sha256:hash(b)});if(path==='tools/test-captured-guns.mjs')continue;const parent=execFileSync('git',['show',PARENT+':'+path],{cwd:ROOT,maxBuffer:2*1024*1024});parentBindings.push({path,bytes:parent.length,sha256:hash(parent)});let virtual=b.toString();for(const e of OWNED_EDITS.filter(e=>e.path===path).reverse()){assert.equal(virtual.split(e.after).length,e.count+1,path+' inverse cardinality');virtual=virtual.split(e.after).join(e.before);}if(path==='tools/test-surrender-activation-ui.mjs'){assert.equal(virtual.split('"captured-guns-model",').length,2);virtual=virtual.replace('"captured-guns-model",','');}assert.deepEqual(Buffer.from(virtual),parent,path+' exact owned inverse');if(!b.equals(parent))changed++;}assert.equal(changed,9);const absent=spawnSync('git',['cat-file','-e',PARENT+':tools/test-captured-guns.mjs'],{cwd:ROOT,stdio:'ignore'});assert.equal(absent.status,128);return{sources,sourceInverse:{all65ParentExact:true,parentBindings,changed:10,locked:56,newProbeAbsentInParent:true}};}
export async function runCapturedGuns(){setup();const source=sourceProof(),reference=await originalGame(),normal=defaultRows(reference.GameClass),original=captureRows(reference.GameClass),captured=captureRows(Game),a2=captureRows(reference.GameClass);assert.deepEqual(a2,original,'Original captured A2 byte-exact A');assert.equal(JSON.stringify(a2),JSON.stringify(original));const defaults=normal.filter(r=>r.implementation==='reference'&&r.flag==='absent').map(r=>({id:r.side+'-'+r.mode,side:r.side,mode:r.mode,frames:r.frames}));const comparisons=normal.map(r=>{const c=defaults.find(c=>c.side===r.side&&c.mode===r.mode);assert.deepEqual(r.frames,c.frames,'Complete actual default candidate/reference/A2 frames');return{id:c.id,implementation:r.implementation,flag:r.flag,fullBytes:r.bytes,fullSha256:r.sha256,frameHashes:r.frames.map(f=>hash(rawText(f))),slotAndRosterRefsExact:r.slotAndRosterRefsExact,rngRefsExact:r.rngRefsExact,gpu:r.gpu,maxInitialFigures:r.maxInitialFigures};});const payload={version:1,defaults,originalCaptured:snapshotTable(original),captured:snapshotTable(captured)};const canonical=encodeRaw(payload);const reconstructed=decodeCapturedRaw(canonical);assert.deepEqual(reconstructed.defaults,defaults);assert.deepEqual(restoreTable(reconstructed.originalCaptured),original);assert.deepEqual(restoreTable(reconstructed.captured),captured);const record={parent:PARENT,...source,originalImports:reference.imports,canonical,defaultComparisons:comparisons,originalA2:{rows:16,bytes:Buffer.byteLength(rawText(a2)),sha256:hash(rawText(a2)),exactA:true},freshFixtures:16,detached:captured.map(r=>r.detached),malformed:malformedProof(),categories:[],controls:[],native:false,scope:'Actual CPU original A/current B/original A2; initialized synthetic recoil, no live-fire/GPU/native/retake/recrew/loot/history authority'};const inputs=capturedCategoryInputs(record);record.categories=inputs.map((data,i)=>{verifyCapturedGun(i,data);return{name:CAPTURED_GUNS_NAMES[i],dataSha256:hash(rawText(data))};});record.controls=inputs.map((data,i)=>{let e;try{verifyCapturedGun(i,capturedGunMutation(i,data));}catch(error){e=error;}assert.equal(e?.code,'ERR_ASSERTION');assert.equal(e.message,CAPTURED_GUNS_NAMES[i]);return{name:CAPTURED_GUNS_NAMES[i],code:e.code,message:e.message};});verifyCapturedGunRecord(record);assert.deepEqual(sourceProof(),source);return record;}
const direct=process.argv[1]&&fs.existsSync(process.argv[1])&&fs.realpathSync(process.argv[1])===fileURLToPath(import.meta.url);
if(direct){try{const r=await runCapturedGuns(),line='CAPTURED GUNS ACTUAL '+JSON.stringify(r);assert(Buffer.byteLength(line)<=4*1024*1024);console.log(line);console.log('CAPTURED GUNS OK (12/12)');if(process.argv.includes('--prove-fail')){for(const c of r.controls)console.log('CAUGHT '+c.name+' '+c.code+' '+c.message);console.log('CAPTURED GUNS CONTROLS '+JSON.stringify(r.controls));console.log('CAPTURED GUNS MUTANTS CAUGHT (12/12; semantic readers)');}}catch(e){console.error('CAPTURED GUNS FAILED '+(e.code||e.name)+' '+e.message.split('\n')[0].slice(0,200));process.exitCode=1;}}
